package vn.rtr.aeris.diagnostic;
import android.app.Activity;import android.content.Intent;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.Color;import android.hardware.input.InputManager;import android.media.*;import android.util.DisplayMetrics;
import java.util.*;import java.text.SimpleDateFormat;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
/** Public Android diagnostic APIs only. No network, SDK vehicle transport or flight bindings. */
public final class DiagnosticActivity extends Activity implements InputManager.InputDeviceListener {
 private final CaptureSession session=new CaptureSession();private final Map<String,Map<String,Object>> observations=new LinkedHashMap<>();
 private TextView status,inventory,trace,previous;private EditText alias,revision;private Button capture;private InputManager inputs;private String pendingExport;private long lastAxis=0;private boolean registered=false;
 private long now(){return SystemClock.elapsedRealtime();}private int dp(int v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}
 private TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(8),0,dp(8));return t;}
 private Button button(String name,android.view.View.OnClickListener click){Button b=new Button(this);b.setText(name);b.setTextSize(13);b.setMinHeight(dp(48));b.setAllCaps(false);b.setOnClickListener(click);return b;}
 private EditText field(String hint){EditText e=new EditText(this);e.setHint(hint);e.setSingleLine(true);e.setTextSize(14);e.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(80)});e.setMinHeight(dp(48));return e;}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);session.lifecycle("create",now());for(String id:Arrays.asList("build","window","inputs","codecs"))observations.put(id,CaptureSession.map("id",id,"source",id.equals("build")?"android.os.Build":id.equals("window")?"android.view.Window":id.equals("inputs")?"android.view.InputDevice":"android.media.MediaCodecList","status","unknown","atElapsedMs",now(),"value",null));LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(Color.rgb(245,246,246));
  TextView header=text("RtR  /  AERIS\nNATIVE DIAGNOSTICS · 0.6",17,Color.WHITE);header.setBackgroundColor(Color.rgb(17,20,23));header.setPadding(dp(24),dp(18),dp(24),dp(18));root.addView(header);
  ScrollView scroll=new ScrollView(this);LinearLayout body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(24),dp(14),dp(24),dp(18));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  body.addView(text("HeraHub · Cấu hình native",26,Color.rgb(20,30,38)));body.addView(text("Chẩn đoán cục bộ. Không kết nối radio, điều khiển bay hoặc đo hiệu năng video.",13,Color.rgb(100,113,123)));
  alias=field("Mã thiết bị do người kiểm khai báo");revision=field("Revision / cấu hình (nếu biết)");body.addView(alias);body.addView(revision);if(saved!=null){alias.setText(saved.getString("alias",""));revision.setText(saved.getString("revision",""));}
  status=text("Đang đọc Android APIs…",13,Color.rgb(60,79,92));body.addView(status);previous=text("",12,Color.rgb(100,113,123));body.addView(previous);readPrevious();
  body.addView(button("Đọc lại cấu hình",v->probe()));inventory=text("",13,Color.rgb(20,30,38));body.addView(inventory);
  body.addView(text("INPUT / LIFECYCLE",11,Color.rgb(100,113,123)));body.addView(text("Bật để quan sát joystick/gamepad khi ứng dụng có focus. Không thu ký tự bàn phím, không ánh xạ sang lệnh bay. Mất focus sẽ dừng ghi.",13,Color.rgb(100,113,123)));
  capture=button("Bắt đầu quan sát input",v->{session.capture(!session.capturing(),now());updateCapture();});body.addView(capture);trace=text("Chưa ghi input",12,Color.rgb(70,86,97));body.addView(trace);
  body.addView(text("UNKNOWN / CHƯA TÍCH HỢP\nRadio transport · Channel map · Calibration · Live video · Decoder concurrency · RTK · Controller battery API",13,Color.rgb(100,113,123)));
  Button export=button("Xuất báo cáo JSON",v->export());export.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.rgb(237,198,44)));root.addView(export,new LinearLayout.LayoutParams(-1,dp(56)));setContentView(root);inputs=(InputManager)getSystemService(INPUT_SERVICE);root.post(this::probe);
 }
 @Override protected void onStart(){super.onStart();session.lifecycle("start",now());if(inputs!=null&&!registered){inputs.registerInputDeviceListener(this,new Handler(Looper.getMainLooper()));registered=true;}}
 @Override protected void onResume(){super.onResume();session.lifecycle("resume",now());if(inventory!=null)inventory.post(this::probe);}
 @Override protected void onPause(){session.lifecycle("pause",now());updateCapture();checkpoint();super.onPause();}
 @Override protected void onStop(){session.lifecycle("stop",now());if(inputs!=null&&registered){inputs.unregisterInputDeviceListener(this);registered=false;}super.onStop();}
 @Override protected void onDestroy(){session.lifecycle("destroy",now());super.onDestroy();}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);session.lifecycle(focus?"focus-gained":"focus-lost",now());if(capture!=null)updateCapture();}
 @Override protected void onSaveInstanceState(Bundle state){state.putString("alias",alias.getText().toString());state.putString("revision",revision.getText().toString());super.onSaveInstanceState(state);}
 private interface Reader{Object read()throws Exception;}
 private void observe(String id,String source,Reader reader){try{Object value=reader.read();CaptureSession.json(value);observations.put(id,CaptureSession.map("id",id,"source",source,"status","observed","atElapsedMs",now(),"value",value));}catch(Exception e){observations.put(id,CaptureSession.map("id",id,"source",source,"status","unknown","atElapsedMs",now(),"value",null,"error",e.getClass().getSimpleName()));}}
 private void probe(){
  observe("build","android.os.Build",()->CaptureSession.map("manufacturer",Build.MANUFACTURER,"model",Build.MODEL,"hardware",Build.HARDWARE,"osRelease",Build.VERSION.RELEASE,"api",Build.VERSION.SDK_INT,"buildFingerprint",Build.FINGERPRINT,"abis",Arrays.asList(Build.SUPPORTED_ABIS)));
  observe("window","android.view.Window",()->{DisplayMetrics m=getResources().getDisplayMetrics();View decor=getWindow().getDecorView();WindowInsets i=decor.getRootWindowInsets();if(i==null||decor.getWidth()==0)throw new IllegalStateException("Window not laid out");return CaptureSession.map("widthPx",decor.getWidth(),"heightPx",decor.getHeight(),"densityDpi",m.densityDpi,"density",m.density,"rotation",getWindowManager().getDefaultDisplay().getRotation(),"insetsPx",CaptureSession.map("left",i.getSystemWindowInsetLeft(),"top",i.getSystemWindowInsetTop(),"right",i.getSystemWindowInsetRight(),"bottom",i.getSystemWindowInsetBottom()));});
  observe("inputs","android.view.InputDevice",()->{List<Object> devices=new ArrayList<>();for(int id:InputDevice.getDeviceIds()){if(devices.size()>=64)throw new IllegalStateException("Input inventory exceeds bound");InputDevice d=InputDevice.getDevice(id);if(d==null)continue;List<Object> ranges=new ArrayList<>();for(InputDevice.MotionRange r:d.getMotionRanges()){if(ranges.size()>=64)throw new IllegalStateException("Motion ranges exceed bound");ranges.add(CaptureSession.map("axis",r.getAxis(),"source",r.getSource(),"min",r.getMin(),"max",r.getMax(),"flat",r.getFlat(),"fuzz",r.getFuzz(),"resolution",r.getResolution()));}devices.add(CaptureSession.map("id",id,"name",d.getName(),"descriptorSha256",hash(d.getDescriptor()),"vendorId",d.getVendorId(),"productId",d.getProductId(),"sources",d.getSources(),"virtual",d.isVirtual(),"ranges",ranges));}return devices;});
  observe("codecs","android.media.MediaCodecList",()->{List<Object> codecs=new ArrayList<>();for(MediaCodecInfo c:new MediaCodecList(MediaCodecList.ALL_CODECS).getCodecInfos()){if(c.isEncoder())continue;for(String mime:c.getSupportedTypes())if((mime.equals("video/avc")||mime.equals("video/hevc"))){if(codecs.size()>=128)throw new IllegalStateException("Codec inventory exceeds bound");codecs.add(CaptureSession.map("name",c.getName(),"mime",mime,"hardwareAccelerated",Build.VERSION.SDK_INT>=29?c.isHardwareAccelerated():null));}}return codecs;});
  status.setText("Android APIs tự báo cáo · chưa xác nhận đây là HeraHub / chưa có attestation");StringBuilder s=new StringBuilder();for(Map<String,Object> o:observations.values())s.append(o.get("id")).append(" / ").append(o.get("status")).append("\n").append(CaptureSession.json(o.get("value"))).append("\n\n");inventory.setText(s.toString());
 }
 private String utc(){SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'",Locale.US);f.setTimeZone(TimeZone.getTimeZone("UTC"));return f.format(new Date());}
 private String context(){return Build.FINGERPRINT.startsWith("generic")||Build.MODEL.toLowerCase(Locale.US).contains("sdk")||Build.HARDWARE.contains("goldfish")||Build.HARDWARE.contains("ranchu")?"emulator":"physical-or-unknown";}
 private String report(){Map<String,Object> r=session.report(utc(),context(),alias.getText().toString(),revision.getText().toString(),BuildInfo.SOURCE_ID,new ArrayList<>(observations.values()));r.put("elapsedAtExport",now());return CaptureSession.json(r);}
 private File priorFile(){return new File(getFilesDir(),"previous-capture.json");}
 private void checkpoint(){try{byte[] bytes=report().getBytes(StandardCharsets.UTF_8);if(bytes.length>524288)throw new IOException("Report too large");File tmp=new File(getFilesDir(),"capture.tmp");try(FileOutputStream out=new FileOutputStream(tmp)){out.write(bytes);out.getFD().sync();}if(!tmp.renameTo(priorFile()))throw new IOException("Rename failed");}catch(Exception e){if(status!=null)status.setText("Checkpoint chưa lưu: "+e.getClass().getSimpleName());}}
 private void readPrevious(){try{File p=priorFile();if(!p.exists()){previous.setText("Phiên mới / không có checkpoint cũ");return;}if(p.length()>524288)throw new IOException();byte[] bytes=new byte[(int)p.length()];try(DataInputStream in=new DataInputStream(new FileInputStream(p))){in.readFully(bytes);}org.json.JSONObject old=new org.json.JSONObject(new String(bytes,StandardCharsets.UTF_8));previous.setText("Có snapshot phiên trước: "+old.optString("captureId")+"\nChỉ là lịch sử; chưa khôi phục trạng thái input/window hiện tại.");}catch(Exception e){previous.setText("Snapshot cũ không đọc được; không khôi phục trạng thái.");}}
 private void export(){try{if(alias.getText().toString().trim().isEmpty())throw new IllegalArgumentException("Khai mã thiết bị trước khi xuất");pendingExport=report();if(pendingExport.getBytes(StandardCharsets.UTF_8).length>524288)throw new IllegalArgumentException("Báo cáo vượt 512 KiB");Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("application/json");intent.putExtra(Intent.EXTRA_TITLE,"aeris-native-"+session.id+".json");startActivityForResult(intent,7);}catch(Exception e){status.setText("Không xuất: "+e.getMessage());}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=7)return;try{if(result==RESULT_OK&&data!=null&&data.getData()!=null&&pendingExport!=null){try(OutputStream out=getContentResolver().openOutputStream(data.getData(),"wt")){if(out==null)throw new IOException();out.write(pendingExport.getBytes(StandardCharsets.UTF_8));}status.setText("Đã xuất snapshot trước khi mở file picker; input đã dừng khi mất focus.");}}catch(Exception e){status.setText("Xuất thất bại: "+e.getClass().getSimpleName());}finally{pendingExport=null;}}
 private void updateCapture(){capture.setText(session.capturing()?"Dừng quan sát input":"Bắt đầu quan sát input");if(trace!=null)trace.setText("Input capture: "+(session.capturing()?"ON":"OFF")+" / không có flight binding");}
 private static boolean control(int source){return (source&InputDevice.SOURCE_GAMEPAD)==InputDevice.SOURCE_GAMEPAD||(source&InputDevice.SOURCE_JOYSTICK)==InputDevice.SOURCE_JOYSTICK;}
 @Override public boolean dispatchKeyEvent(KeyEvent e){if(session.capturing()&&control(e.getSource())&&e.getAction()!=KeyEvent.ACTION_MULTIPLE){session.raw("key",e.getEventTime(),CaptureSession.map("deviceId",e.getDeviceId(),"source",e.getSource(),"keyCode",e.getKeyCode(),"action",e.getAction(),"repeat",e.getRepeatCount()));trace.setText("Gamepad key "+e.getKeyCode()+" / action "+e.getAction()+" / không ánh xạ bay");}return super.dispatchKeyEvent(e);}
 @Override public boolean dispatchGenericMotionEvent(MotionEvent e){if(session.capturing()&&control(e.getSource())&&now()-lastAxis>=50){lastAxis=now();InputDevice d=e.getDevice();if(d!=null){List<Object> axes=new ArrayList<>();for(InputDevice.MotionRange r:d.getMotionRanges())if(axes.size()<64&&(e.getSource()&r.getSource())==r.getSource())axes.add(CaptureSession.map("axis",r.getAxis(),"value",e.getAxisValue(r.getAxis())));try{session.raw("axis",e.getEventTime(),CaptureSession.map("deviceId",e.getDeviceId(),"source",e.getSource(),"axes",axes));trace.setText("Joystick device "+e.getDeviceId()+" / "+CaptureSession.json(axes));}catch(IllegalArgumentException bad){trace.setText("Input không hữu hạn đã bỏ");}}}return super.dispatchGenericMotionEvent(e);}
 @Override public void onInputDeviceAdded(int id){session.lifecycle("input-added",now(),CaptureSession.map("deviceId",id));probe();} @Override public void onInputDeviceRemoved(int id){session.lifecycle("input-removed",now(),CaptureSession.map("deviceId",id));session.capture(false,now());updateCapture();probe();} @Override public void onInputDeviceChanged(int id){session.lifecycle("input-changed",now(),CaptureSession.map("deviceId",id));session.capture(false,now());updateCapture();probe();}
 private static String hash(String text)throws Exception{byte[] b=MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format("%02x",v&255));return s.toString();}
}
